            </Text>
          </div>
        )}
      </div>
      </>}

{() => {
                    // Narrowed inside the callback rather than asserted: the
                    // enclosing guard does not survive into the closure.
                    if (plan.recommendedShares != null) patch({ shares: plan.recommendedShares });
