export function IndicatorPanel({ chart, data, type }: IndicatorPanelProps) {
  const paneIndexRef = useRef<number | null>(null);
  const seriesRef = useRef<(ISeriesApi<'Line'> | ISeriesApi<'Histogram'>)[]>([]);

  useEffect(() => {
    if (!chart) return;

    if (type === 'rsi') {
      const pane = chart.addPane();
      pane.setStretchFactor(0.3);
      paneIndexRef.current = pane.paneIndex();

      const series = pane.addSeries(LineSeries, {
        color: token('--accent') || '#2962FF',
        lineWidth: 2,
        priceLineVisible: false,
        lastValueVisible: false,
        autoscaleInfoProvider: () => ({
          priceRange: { minValue: 0, maxValue: 100 },
        }),
      });
      seriesRef.current = [series];

      series.createPriceLine({
        price: 30,
        color: token('--text-dim') || '#434651',
        lineWidth: 1,
        lineStyle: 2,
      });
      series.createPriceLine({
        price: 70,
        color: token('--text-dim') || '#434651',
        lineWidth: 1,
        lineStyle: 2,
      });
    } else if (type === 'macd') {
      const pane = chart.addPane();
      pane.setStretchFactor(0.3);
      paneIndexRef.current = pane.paneIndex();

      const macdSeries = pane.addSeries(LineSeries, {
        color: token('--accent') || '#2962FF',
        lineWidth: 2,
        priceLineVisible: false,
        lastValueVisible: false,
      });
      const signalSeries = pane.addSeries(LineSeries, {
        color: token('--caution') || '#F59F00',
        lineWidth: 2,
        priceLineVisible: false,
        lastValueVisible: false,
      });
      const histSeries = pane.addSeries(HistogramSeries, {
        color: token('--text-secondary') || '#787B86',
        priceLineVisible: false,
        lastValueVisible: false,
      });
      seriesRef.current = [macdSeries, signalSeries, histSeries];
    } else if (type === 'volume') {
      const pane = chart.addPane();
      pane.setStretchFactor(0.3);
      paneIndexRef.current = pane.paneIndex();

      const series = pane.addSeries(HistogramSeries, {
        priceFormat: { type: 'volume' },
        priceLineVisible: false,
        lastValueVisible: false,
      });
      seriesRef.current = [series];
    }

    return () => {
      if (paneIndexRef.current !== null) {
        try {
          chart.removePane(paneIndexRef.current);
        } catch {
          /* pane may already be gone */
        }
        paneIndexRef.current = null;
      }
      seriesRef.current = [];
    };
  }, [chart, type]);

  useEffect(() => {
    if (seriesRef.current.length === 0 || data.length === 0) return;

    if (type === 'rsi') {
      seriesRef.current[0].setData(
        (data as RsiPoint[]).map((d) => ({
          time: d.time as Time,
          value: d.value,
        })),
      );
    } else if (type === 'macd') {
      seriesRef.current[0].setData(
        (data as MacdPoint[]).map((d) => ({
          time: d.time as Time,
          value: d.macd,
        })),
      );
      seriesRef.current[1].setData(
        (data as MacdPoint[]).map((d) => ({
          time: d.time as Time,
          value: d.signal,
        })),
      );
      seriesRef.current[2].setData(
        (data as MacdPoint[]).map((d) => ({
          time: d.time as Time,
          value: d.histogram,
          color:
            d.histogram >= 0
              ? token('--pass') || '#26A69A'
              : token('--reject') || '#EF5350',
        })),
      );
    } else if (type === 'volume') {
      seriesRef.current[0].setData(
        (data as VolumePoint[]).map((d) => ({
          time: d.time as Time,
          value: d.value,
          color:
            d.color === 'up'
              ? token('--pass') || '#26A69A'
              : token('--reject') || '#EF5350',
        })),
      );
    }
  }, [data, type]);

  return null;
}

export function ChartOverlays({ chart, mainSeries, signals, visibility, visible }: Props) {
  const attachedRef = useRef<ISeriesPrimitive[]>([]);

  useEffect(() => {
    if (!chart || !mainSeries) return;
    const series = mainSeries;

    for (const p of attachedRef.current) {
      try { series.detachPrimitive(p); } catch { /* ignore */ }
    }
    attachedRef.current = [];

    if (!visible) return;

    for (const signal of signals) {
      if (!visibility[signal.kind]) continue;
      let primitive: ISeriesPrimitive | null = null;
      switch (signal.kind) {
        case 'FVG':
          primitive = new FVGPrimitive(signal);
          break;
        case 'OrderBlock':
          primitive = new OrderBlockPrimitive(signal as ZoneSignal);
          break;
        case 'BOS':
        case 'CHoCH':
          primitive = new BOSPrimitive(signal);
          break;
        case 'Fibonacci':
          primitive = new FibPrimitive(signal);
          break;
        case 'Divergence':
          primitive = new DivergencePrimitive(signal);
          break;
        case 'Confluence':
          primitive = new ConfluencePrimitive(signal);
          break;
      }
      if (primitive) {
        series.attachPrimitive(primitive);
        attachedRef.current.push(primitive);
      }
    }

    return () => {
      for (const p of attachedRef.current) {
        try { series.detachPrimitive(p); } catch { /* ignore */ }
      }
      attachedRef.current = [];
    };
  }, [chart, mainSeries, signals, visibility, visible]);

  return null;
}

export default function DrawingOverlays({ chart, mainSeries, drawings }: Props) {
  const attachedRef = useRef<Map<string, AttachedEntry>>(new Map());

  useEffect(() => {
    if (!chart || !mainSeries) return;
    const attached = attachedRef.current;
    const { toAdd, toRemove, toUpdate } = diffDrawings(attached, drawings);

    for (const entry of toRemove) {
      try {
        mainSeries.detachPrimitive(entry.primitive);
      } catch (e) {
        if (process.env.NODE_ENV !== 'production') throw e;
      }
      attached.delete(entry.drawing.id);
    }

    for (const { entry, drawing } of toUpdate) {
      entry.primitive.update(drawing);
      attached.set(drawing.id, { primitive: entry.primitive, drawing });
    }

    for (const drawing of toAdd) {
      const primitive = makePrimitive(drawing);
      if (!primitive) continue;
      mainSeries.attachPrimitive(primitive);
      attached.set(drawing.id, { primitive, drawing });
    }
  }, [chart, mainSeries, drawings]);

  useEffect(() => {
    return () => {
      const attached = attachedRef.current;
      for (const entry of attached.values()) {
        try {
          mainSeries?.detachPrimitive(entry.primitive);
        } catch (e) {
          if (process.env.NODE_ENV !== 'production') throw e;
        }
      }
      attached.clear();
    };
  }, [chart, mainSeries]);

  return null;
}

